<?php
declare(strict_types=1);
namespace App\Http\Controllers\Academic;
use App\Http\Controllers\Controller;use App\Models\{AcademicYear,Semester,StudentAttendance,StudentGrade,TeachingJournal};use App\Services\Academic\AcademicAccessService;use Illuminate\Http\Request;use Illuminate\View\View;
class ReportController extends Controller {public function __invoke(Request $r,AcademicAccessService $a):View{$year=$r->integer('academic_year_id')?:AcademicYear::where('is_active',true)->value('id');$semester=$r->integer('semester_id')?:Semester::where('academic_year_id',$year)->where('is_active',true)->value('id');$roomId=$r->integer('classroom_id');$room=$roomId?$a->ensureClassroom($r->user(),$roomId):null;$students=$room?->students()->orderBy('full_name')->get()??collect();$studentId=$r->integer('student_id');if($studentId&&!$students->contains('id',$studentId))abort(422,'Siswa tidak terdaftar pada rombel ini.');$attendance=StudentAttendance::where(['semester_id'=>$semester,'classroom_id'=>$roomId])->get()->groupBy('student_id');$grades=StudentGrade::with('subject')->where(['semester_id'=>$semester,'classroom_id'=>$roomId])->get()->groupBy('student_id');$from=$r->date('from_date')?->toDateString()??today()->startOfMonth()->toDateString();$to=$r->date('to_date')?->toDateString()??today()->toDateString();$teachingRecap=TeachingJournal::with(['personnel','classroom','subject'])->where('academic_year_id',$year)->whereBetween('journal_date',[$from,$to])->get();return view('academic.reports.index',compact('year','semester','room','students','studentId','attendance','grades','from','to','teachingRecap')+['years'=>AcademicYear::orderByDesc('starts_at')->get(),'semesters'=>Semester::where('academic_year_id',$year)->get(),'rooms'=>$a->classrooms($r->user())->where('academic_year_id',$year)->get()]);}}
